// Valida las dos preguntas del Supuesto 7
const body = items[0].json.body;
const esPropietario = body.es_propietario === true || body.es_propietario === 'si';
const reciboLuz = parseFloat(body.monto_recibo_luz || 0);
const telefonoValido = body.telefono && body.telefono.length >= 8;

const calificadoParaVisita = esPropietario && reciboLuz >= 80.0 && telefonoValido;

return [{
  json: {
    nombre: body.nombre,
    telefono: body.telefono,
    canal: body.canal || 'META',
    es_propietario: esPropietario,
    monto_recibo_luz: reciboLuz,
    calificado: calificadoParaVisita
  }
}];
